mapper.select:
select O.ORDER_NO as orderNo, O.PAYMENT_ORDER_NO as paymentOrderNo, O.TRADE_NO as tradeNo, O.TICKET_NAME as ticketName, O.TICKET_PRICE as ticketPrice, O.PAY_AMOUNT as payAmount, O.PAY_CHANNEL_CODE as payChannelCode, O.ORDER_STATUS as orderStatus, O.PAY_STATUS as payStatus, O.PAY_DATE as payDate, O.CREATE_TIME as createTime, I.TICKET_STATUS as ticketStatus, I.CARD_NUM as cardNum, R.REFUND_ORDER_NO as refundOrderNo, R.PLATFORM_REFUND_NO as platformRefundNo, R.REFUND_STATUS as refundStatus, R.REFUND_TYPE as refundType, R.REFUND_AMOUNT as refundAmount, R.REFUND_DATE as refundDate, R.VERIFY_AFTER_TIME as verifyAfterTime from DAILY_TICKET_ORDER O left join DAILY_TICKET_INSTANCE I on I.ORDER_NO = O.ORDER_NO left join DAILY_TICKET_REFUND R on R.ORDER_NO = O.ORDER_NO
and O.CREATE_TIME >= #{beginTime,jdbcType=TIMESTAMP}
and O.CREATE_TIME <= #{endTime,jdbcType=TIMESTAMP}
and O.ORDER_NO = #{orderNo,jdbcType=VARCHAR}
and O.PAYMENT_ORDER_NO = #{paymentOrderNo,jdbcType=VARCHAR}
order by O.CREATE_TIME desc
